import {apps,clone,visible,albumPhotos} from './domain.js';
import {initialProgress,step} from './engine-v3.js';
import {esc,image,safeSrc,button,toast} from './ui.js';
export class Phone {
 constructor({story,mode='edit',progress,onProgress=()=>{},onSelect=()=>{},onDebug=()=>{}}){this.story=story;this.mode=mode;this.p=progress||initialProgress(story);this.onProgress=onProgress;this.onSelect=onSelect;this.onDebug=onDebug;this.page=this.p.phoneUnlocked?'home':'lock';this.code='';this.viewer=null;this.albumId='';this.translation={};this.transcripts={};this.voice=null;this.voiceId=null;this.callAudio=null;this.ring=null;this.stream=null;this.cameraError='카메라를 사용하려면 권한을 허용해 주세요.';this.cameraPending=false;this.filterUnread=false;this.galleryScroll=0;this.homePage=0;this.typing=false;this.destroyed=false;}
 mount(root){this.root=root;root.onclick=e=>this.click(e);root.ondblclick=e=>{if(this.viewer?.kind==='photos'&&e.target.closest('.viewer-stage'))this.zoom(this.viewer.scale>1?1:2);};root.onwheel=e=>{if(this.viewer?.kind==='photos'&&e.target.closest('.viewer-stage')){e.preventDefault();this.zoom(this.viewer.scale+(e.deltaY<0?.25:-.25));}};root.addEventListener('pointerdown',this.pointerDown=e=>this.down(e));root.addEventListener('pointermove',this.pointerMove=e=>this.move(e));root.addEventListener('pointerup',this.pointerUp=e=>this.up(e));root.addEventListener('pointercancel',this.pointerUp);this.render();if(this.mode!=='edit'&&!this.p.started)this.dispatch({type:'start'});this.clock=setInterval(()=>this.tick(),300);this.timeClock=setInterval(()=>this.updateTime(),1000);}
 destroy(){this.destroyed=true;clearInterval(this.clock);clearInterval(this.timeClock);clearInterval(this.typingTimer);this.observer?.disconnect();this.stopVoice();this.stopCall();this.releaseCamera();this.endingAudio?.pause();if(this.root){this.root.onclick=null;this.root.ondblclick=null;this.root.onwheel=null;this.root.removeEventListener('pointerdown',this.pointerDown);this.root.removeEventListener('pointermove',this.pointerMove);this.root.removeEventListener('pointerup',this.pointerUp);this.root.removeEventListener('pointercancel',this.pointerUp);}}
 dispatch(input,render=true){if(this.mode==='edit')return;const out=step(this.story,this.p,input,Date.now());this.p=out.progress;for(const fx of out.effects)this.effect(fx);if(this.page.startsWith('room:'))this.p.unread[this.page.slice(5)]=0;this.onProgress(clone(this.p));this.onDebug(this.p);if(render)this.render();else {const layer=this.root?.querySelector('.phone-overlays');if(layer)layer.innerHTML=this.overlays();}}
 tick(){if(this.mode==='edit'||document.hidden)return;const before=JSON.stringify([this.p.arrived,this.p.unlocked,this.p.hidden,this.p.call,this.p.callQueue,this.p.notification,this.p.ending,this.p.variables,this.p.systemMessages]);this.dispatch({type:'tick'},false);const after=JSON.stringify([this.p.arrived,this.p.unlocked,this.p.hidden,this.p.call,this.p.callQueue,this.p.notification,this.p.ending,this.p.variables,this.p.systemMessages]);if(before!==after)this.render();else {if(this.page.startsWith('note:')){const state=this.p.notePasswords[this.page.slice(5)];if(state?.until&&state.until<=Date.now()&&this.cooldownRendered!==state.until){this.cooldownRendered=state.until;this.render();}}const timer=this.root?.querySelector('[data-call-duration]');if(timer)timer.textContent=this.callDuration();}}
 effect(fx){if(fx.type==='call.ring'){this.voice?.pause();const c=this.story.calls.find(x=>x.id===fx.id);this.playRing(c?.ringtone);}if(fx.type==='call.stop')this.stopCall();if(fx.type==='call.accept'){clearInterval(this.ringTimer);this.ring?.pause();const c=this.story.calls.find(x=>x.id===fx.id);if(safeSrc(c?.audio)){this.callAudio=new Audio(safeSrc(c.audio));this.callAudio.play().catch(()=>{this.audioBlocked=true;this.render();});}}if(['message','notice'].includes(fx.type)){if(safeSrc(this.story.phone.messageSound)){const sound=new Audio(safeSrc(this.story.phone.messageSound));sound.play().catch(()=>{});}else this.beep();}if(fx.type==='ending'){this.stopVoice();const e=this.story.endings.find(x=>x.id===fx.id);if(safeSrc(e?.audio)){this.endingAudio=new Audio(safeSrc(e.audio));this.endingAudio.play().catch(()=>{});}}}
 beep(){try{const ctx=this.audioContext;if(!ctx)return;const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=740;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.15);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.16);}catch{}}
 initAudio(){try{this.audioContext??=new(window.AudioContext||window.webkitAudioContext)();this.audioContext.resume();}catch{}}
 playRing(src){if(safeSrc(src)){this.ring=new Audio(safeSrc(src));this.ring.loop=true;this.ring.play().catch(()=>{this.audioBlocked=true;});}else {this.beep();this.ringTimer=setInterval(()=>this.beep(),1800);}}
 stopCall(){clearInterval(this.ringTimer);this.ring?.pause();this.ring=null;this.callAudio?.pause();this.callAudio=null;this.audioBlocked=false;}
 stopVoice(){this.voice?.pause();if(this.voice)this.voice.currentTime=0;this.voice=null;this.voiceId=null;}
 releaseCamera(){this.cameraGeneration=(this.cameraGeneration||0)+1;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.cameraPending=false;}
 async camera(){if(this.stream||this.cameraPending||this.page!=='camera')return;this.cameraPending=true;const generation=this.cameraGeneration||0;try{const stream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});if(this.destroyed||this.page!=='camera'||generation!==(this.cameraGeneration||0)){stream.getTracks().forEach(t=>t.stop());return;}this.stream=stream;this.render();const video=this.root.querySelector('video');if(video){video.srcObject=stream;video.play().catch(()=>{});}}catch{this.cameraError='카메라를 사용할 수 없습니다. 권한과 장치를 확인한 뒤 다시 시도해 주세요.';const el=this.root?.querySelector('.camera-message');if(el)el.textContent=this.cameraError;}finally{this.cameraPending=false;}}
 updateTime(){this.root?.querySelectorAll('[data-local-time]').forEach(x=>x.textContent=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false}));}
 name(id){const c=this.char(id);return c?.remark||c?.name||'알 수 없음';}
 char(id){const c=this.story.characters.find(c=>c.id===id);return c?{...c,...this.p.characterOverrides[id]}:null;}
 avatar(id){const c=this.char(id);return `<span class="avatar">${image(c?.avatar)||esc(c?.name?.slice(0,1)||'●')}</span>`;}
 isVisible(x){return this.mode==='edit'||visible(x,this.p);}
 head(title,back='home',extra=''){return `<header class="app-head">${button('‹','phone.back','','data-to="'+back+'"')}<b>${esc(title)}</b>${extra||'<span aria-hidden="true">⌕　☰</span>'}</header>`;}
 select(kind,id){if(this.mode==='edit'){this.onSelect(kind,id);return true;}return false;}
 event(type,id){if(this.mode!=='edit')this.dispatch({type,id},false);}
 navigate(page){if(this.p.ending&&!this.p.endingDismissed&&this.mode!=='edit')return;if(this.page==='camera'&&page!=='camera')this.releaseCamera();if(page!==this.page)this.stopVoice();const previous=this.page;this.page=page;this.viewer=null;this.code='';this.noteError=false;if(previous.startsWith('note:')){const n=this.story.notes.find(n=>n.id===previous.slice(5));if(n&&!n.remember&&this.p.notePasswords[n.id])this.p.notePasswords[n.id].ok=false;}const [kind,id]=page.split(':');if(kind==='room'){this.event('chat.enter',id);this.event('chat.complete',id);}if(kind==='note')this.event('note.attempt',id);if(kind==='result')this.event('safari.read',id);this.render();if(page==='camera')this.camera();}
 unlock(){this.initAudio();const code=this.story.phone.passcode;if(this.mode==='edit'||!code||this.p.phoneUnlocked){this.dispatch({type:'unlock'},false);this.navigate('home');}else {this.keypad=true;this.render();}}
 target(id){const s=this.story;if(s.rooms.some(x=>x.id===id))this.navigate('room:'+id);else if(s.notes.some(x=>x.id===id))this.navigate('note:'+id);else if(s.photos.some(x=>x.id===id)){this.navigate('photos');this.openPhoto(id);}else if(s.messages.some(x=>x.id===id))this.navigate('room:'+s.messages.find(x=>x.id===id).roomId);else this.navigate('home');}
 openPhoto(id){const photos=albumPhotos(this.story,this.p,this.albumId);if(!photos.some(x=>x.id===id)&&this.mode!=='edit')return;const seq=this.mode==='edit'?this.story.photos:photos;this.galleryScroll=this.root.querySelector('.photo-grid')?.scrollTop||0;const p=this.story.photos.find(x=>x.id===id);if(p?.trigger==='display')this.event('photo.display',id);this.viewer={kind:'photos',ids:seq.map(x=>x.id),index:seq.findIndex(x=>x.id===id),scale:1,x:0,y:0};this.renderViewer();}
 openViewer(kind,ids,index=0){this.viewer={kind,ids,index,scale:1,x:0,y:0};this.renderViewer();}
 zoom(scale){const v=this.viewer;if(v?.kind!=='photos')return;v.scale=Math.min(4,Math.max(1,scale));if(v.scale===1){v.x=0;v.y=0;}const photo=this.story.photos.find(x=>x.id===v.ids[v.index]);if(v.scale>1&&photo?.trigger==='zoom')this.event('photo.zoom',photo.id);this.transform();}
 transform(){const v=this.viewer,img=this.root.querySelector('.viewer-stage img');if(img&&v)img.style.transform=`translate(${v.x}px,${v.y}px) scale(${v.scale})`;if(!v)return;const reset=this.root.querySelector('[data-action="phone.viewer-reset"]'),prev=this.root.querySelector('[data-action="phone.viewer-prev"]'),next=this.root.querySelector('[data-action="phone.viewer-next"]');if(reset)reset.textContent=Math.round(v.scale*100)+'%';if(prev)prev.disabled=v.index===0||v.scale>1;if(next)next.disabled=v.index===v.ids.length-1||v.scale>1;}
 switchPhoto(delta){const v=this.viewer;if(!v||v.kind==='chat'||v.scale>1)return;const index=v.index+delta;if(index<0||index>=v.ids.length)return;v.index=index;v.x=v.y=0;if(v.kind==='photos'){const p=this.story.photos.find(x=>x.id===v.ids[v.index]);if(p?.trigger==='display')this.event('photo.display',p.id);}this.renderViewer();}
 down(e){this.pointers??=new Map();this.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(this.viewer&&e.target.closest('.viewer-stage')){e.preventDefault();e.target.setPointerCapture?.(e.pointerId);this.drag={x:e.clientX,y:e.clientY,px:this.viewer.x,py:this.viewer.y};if(this.pointers.size===2){const [a,b]=[...this.pointers.values()];this.pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),scale:this.viewer.scale};}}else if(this.page==='lock')this.lockDrag=e.clientY;}
 move(e){if(!this.pointers?.has(e.pointerId))return;this.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(!this.viewer)return;if(this.viewer.kind==='photos'&&this.pointers.size===2&&this.pinch){const [a,b]=[...this.pointers.values()];this.zoom(this.pinch.scale*Math.hypot(a.x-b.x,a.y-b.y)/this.pinch.distance);return;}if(this.viewer.scale>1&&this.drag){const limit=240*(this.viewer.scale-1);this.viewer.x=Math.max(-limit,Math.min(limit,this.drag.px+e.clientX-this.drag.x));this.viewer.y=Math.max(-limit,Math.min(limit,this.drag.py+e.clientY-this.drag.y));this.transform();}}
 up(e){const wasPinch=this.pointers?.size>=2;if(this.viewer&&this.drag&&!wasPinch&&!this.pinch&&this.viewer.scale===1){const dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(this.viewer.kind==='profile'&&Math.abs(dy)>40)this.switchPhoto(dy<0?1:-1);if(this.viewer.kind==='photos'&&Math.abs(dx)>40)this.switchPhoto(dx<0?1:-1);}if(this.page==='lock'&&this.lockDrag-e.clientY>50)this.unlock();this.pointers?.delete(e.pointerId);if(!this.pointers?.size){this.pinch=null;this.drag=null;}this.lockDrag=null;}
 render(){if(!this.root)return;const s=this.story,dark=['home','lock','camera'].includes(this.page);this.root.innerHTML=`<div class="phone-shell"><div class="phone-screen ${dark?'dark':''}"><div class="system-bar"><strong data-local-time></strong><span class="dynamic-island"></span><span>${'▮'.repeat(Math.min(4,Math.max(0,s.phone.signal)))} ${esc(s.phone.network)} <span class="battery">${esc(s.phone.battery)}</span></span></div><div class="phone-body">${this.body()}</div><button class="home-indicator" data-action="phone.home" aria-label="${this.page==='lock'?'잠금 해제':'홈 화면'}"><i></i></button><div class="phone-overlays">${this.overlays()}</div><div class="viewer-host"></div></div></div>`;this.updateTime();if(this.page.startsWith('room:')){const list=this.root.querySelector('.chat-scroll');if(list){list.scrollTop=list.scrollHeight;this.observeMessages(list);}}if(this.page==='camera'){const video=this.root.querySelector('video');if(video&&this.stream){video.srcObject=this.stream;video.play().catch(()=>{});}}if(this.page.startsWith('note:')){const n=s.notes.find(x=>x.id===this.page.slice(5));if(n&&(this.isVisible(n)||this.p.noteUnlocked.includes(n.id))&&this.canReadNote(n))this.event('note.read',n.id);}if(this.viewer)this.renderViewer();}
 wallpaper(src,crop){src=safeSrc(src);return src?`background-image:url('${esc(src)}');background-position:${Number(crop?.x)||50}% ${Number(crop?.y)||50}%;background-size:${100*(Number(crop?.scale)||1)}% auto;`:'';}
 body(){const s=this.story,p=this.p;
  if(this.page==='lock')return `<section class="lock-screen wallpaper" style="${this.wallpaper(s.phone.lockWallpaper,s.phone.lockCrop)}"><div class="lock-date">${new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'})}</div><div class="lock-time" data-local-time></div><span class="lock-symbol">▣</span>${this.keypad?`<div class="passcode"><h3>암호 입력</h3><div class="code-dots ${this.error?'shake':''}">${'●'.repeat(this.code.length)}${'○'.repeat(Math.max(0,s.phone.passcode.length-this.code.length))}</div>${this.error?'<p class="error">암호가 올바르지 않습니다</p>':''}<div class="keypad">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(n=>button(String(n),'phone.key','','data-key="'+n+'"')).join('')}</div>${s.phone.hint?button('암호 힌트','phone.hint'):''}</div>`:'<div class="lock-caption">위로 쓸어올려 잠금 해제</div><div class="lock-tools"><span>◉</span><span>▣</span></div>'}</section>`;
  if(this.page==='home'){const appOrder=s.phone.appOrder.filter(id=>!s.phone.hiddenApps.includes(id)),pages=Math.max(1,Math.ceil(appOrder.length/s.phone.pageSize));this.homePage=Math.min(this.homePage,pages-1);const tile=id=>{const a=apps.find(a=>a[0]===id);return a?`<button class="app-tile" data-action="phone.nav" data-to="${id}" draggable="${this.mode==='edit'}" data-app-id="${id}"><span class="app-icon icon-${id}" style="width:${s.phone.iconSize}px;height:${s.phone.iconSize}px">${a[2]}</span><small>${a[1]}</small></button>`:'';};return `<section class="home-screen wallpaper" style="${this.wallpaper(p.wallpaper||s.phone.wallpaper,s.phone.homeCrop)}"><div class="widgets">${s.phone.weather?`<div><small>날씨</small><strong>${esc(s.phone.weatherText)}</strong><span>대체로 맑음</span></div>`:''}${s.phone.dateWidget?`<div><small>${new Date().toLocaleDateString('ko-KR',{weekday:'long'})}</small><strong>${new Date().getDate()}</strong><span>오늘</span></div>`:''}</div><div class="app-grid" style="grid-template-columns:repeat(${s.phone.columns},1fr)">${appOrder.slice(this.homePage*s.phone.pageSize,(this.homePage+1)*s.phone.pageSize).map(tile).join('')}</div><div class="home-pages">${Array.from({length:pages},(_,i)=>button(i===this.homePage?'●':'○','phone.page','','data-index="'+i+'"')).join('')}</div><div class="dock">${s.phone.dock.filter(id=>!s.phone.hiddenApps.includes(id)).slice(0,4).map(tile).join('')}</div></section>`;}
  if(['chat','friends'].includes(this.page)){const friends=this.page==='friends';let rooms=s.rooms.map(r=>({r,ms:s.messages.filter(m=>m.roomId===r.id&&this.isVisible(m)&&(this.mode==='edit'||p.arrived.includes(m.id)))}));rooms.sort((a,b)=>Number(b.r.pinned)-Number(a.r.pinned)||(a.r.pinned?0:this.latestTime(b)-this.latestTime(a)));return this.head(friends?'친구':'채팅')+(!friends?`<div class="chat-filters">${button(this.filterUnread?'전체':'전체 ✓','phone.filter-all')}${button(this.filterUnread?'안 읽음 ✓':'안 읽음','phone.filter-unread')}${button('모두 읽음','phone.allread')}</div>`:'')+`<div class="app-list">${friends?s.characters.filter(c=>c.id!==s.phone.ownerId).map(c=>`<button class="list-row" data-action="phone.nav" data-to="profile:${c.id}">${this.avatar(c.id)}<div><b>${esc(this.name(c.id))}</b><small>${esc(this.char(c.id)?.status)}</small></div></button>`).join(''):rooms.filter(({r})=>!this.filterUnread||p.unread[r.id]>0).map(({r,ms})=>`<button class="list-row" data-action="phone.nav" data-to="room:${r.id}">${this.roomAvatar(r)}<div><b>${r.pinned?'⌖ ':''}${esc(r.name)}</b><small>${esc(ms.at(-1)?.text||'사진')}</small></div>${p.unread[r.id]?`<em>${p.unread[r.id]}</em>`:''}</button>`).join('')}</div><nav class="kakao-tabs">${button('♙<small>친구</small>','phone.nav','','data-to="friends"')}${button('☏<small>채팅</small>','phone.nav','','data-to="chat"')}<span>◎<small>오픈채팅</small></span><span>▢<small>쇼핑</small></span><span>•••<small>더보기</small></span></nav>`;}
  if(this.page.startsWith('room:')){const original=s.rooms.find(x=>x.id===this.page.slice(5));const r=original&&this.replyConfig(original);if(!r)return this.head('채팅');const ms=s.messages.filter(m=>m.roomId===r.id&&this.isVisible(m)&&(this.mode==='edit'||p.arrived.includes(m.id)));const replyOpen=this.translation['reply:'+(r.nodeId||r.id)]??s.phone.translationOpen;const replied=p.replies.some(x=>r.nodeId?x.nodeId===r.nodeId:x.roomId===r.id&&!x.nodeId);return this.head(r.name+(r.group?' '+(p.members[r.id]||r.members).length:''),'chat')+`<div class="chat-scroll"><p class="story-date">${esc(r.startTime.replace('T',' '))}</p>${ms.map(m=>this.message(m)).join('')}${p.systemMessages.filter(x=>x.roomId===r.id).map(x=>`<p class="story-date">${esc(x.text)}</p>`).join('')}${p.replies.filter(x=>x.roomId===r.id&&x.display).map(x=>`<div class="message mine"><div class="bubble">${esc(x.text)}${s.phone.bilingual&&x.zh?`${button((this.translation[x.id]??s.phone.translationOpen)?'중국어 ▴':'중국어 ▾','phone.translation','translation-toggle','data-id="'+x.id+'"')}${(this.translation[x.id]??s.phone.translationOpen)?`<div class="translation">${esc(x.zh)}</div>`:''}`:''}</div></div>`).join('')}</div><div class="chat-input"><span aria-hidden="true">⊕</span>${this.mode==='edit'?button('＋ 添加消息','phone.add-message','','data-id="'+r.id+'"'):replied||r.replyMode==='readonly'?'<span class="readonly-input">메시지를 입력하세요　☺</span>':r.replyMode==='free'?'<input id="reader-reply" aria-label="메시지 입력"><button data-action="phone.reply">↑</button>':r.replyMode==='typing'?button('메시지 입력','phone.typing','typing-input'):button(esc(r.replyText)+(s.phone.bilingual&&r.replyZh&&replyOpen?`<small>${esc(r.replyZh)}</small>`:''),'phone.reply-preset','preset')}${this.mode!=='edit'&&!replied&&r.replyMode==='preset'&&s.phone.bilingual&&r.replyZh?button(replyOpen?'중국어 ▴':'중국어 ▾','phone.reply-translation','translation-toggle','data-id="'+(r.nodeId||r.id)+'"'):''}<span aria-hidden="true">☺</span></div>${this.typing?'<div class="korean-keyboard"><p id="typing-text"></p><div>ㅂ ㅈ ㄷ ㄱ ㅅ ㅛ ㅕ ㅑ ㅐ ㅔ<br>ㅁ ㄴ ㅇ ㄹ ㅎ ㅗ ㅓ ㅏ ㅣ<br>ㅋ ㅌ ㅊ ㅍ ㅠ ㅜ ㅡ</div></div>':''}`;}
  if(this.page.startsWith('profile:')){const c=this.char(this.page.slice(8));if(!c)return this.head('프로필','friends');const r=s.rooms.find(x=>!x.group&&x.characterId===c.id);return this.head('프로필','friends')+`<div class="profile" style="${this.wallpaper(c.background,c.crop)}">${this.avatar(c.id)}<h2>${esc(this.name(c.id))}</h2><p>${esc(c.status)}</p><div class="profile-actions">${c.chatButton&&(!c.chatGate||p.variables[c.chatGate])&&r?button('채팅','phone.nav','','data-to="room:'+r.id+'"'):''}${c.phoneButton&&(!c.phoneGate||p.variables[c.phoneGate])?button('통화','phone.profile-call','','data-id="'+c.id+'"'):''}</div><div class="profile-gallery">${c.gallery.map((src,i)=>`<button data-action="phone.profile-image" data-id="${c.id}" data-index="${i}">${image(src)}</button>`).join('')}</div></div>`;}
  if(this.page==='photos'||this.page==='albums'||this.page.startsWith('album:')){const isAlbums=this.page==='albums',a=s.albums.find(x=>x.id===this.page.slice(6));if(this.page.startsWith('album:'))this.albumId=a?.id||'';else this.albumId='';const photos=this.mode==='edit'?(a?s.photos.filter(x=>a.photoIds.includes(x.id)):s.photos):albumPhotos(s,p,this.albumId);return this.head(isAlbums?'앨범':a?.name||'최근 항목',a?'albums':'home')+(isAlbums?`<div class="album-grid">${s.albums.filter(x=>this.isVisible(x)||x.lockedStyle==='placeholder').map(x=>this.isVisible(x)?`<button data-action="phone.nav" data-to="album:${x.id}">${image(x.cover||s.photos.find(photo=>x.photoIds.includes(photo.id)&&this.isVisible(photo))?.src)}<b>${esc(x.name)}</b></button>`:'<div class="locked-tile">🔒</div>').join('')}</div>`:`<div class="photo-grid">${photos.map(x=>`<button data-action="phone.photo" data-id="${x.id}">${image(x.src)}</button>`).join('')}${s.photos.filter(x=>!this.isVisible(x)&&x.lockedStyle==='placeholder'&&(a?a.photoIds.includes(x.id):s.albums.some(album=>this.isVisible(album)&&album.photoIds.includes(x.id)))).map(()=>'<div class="locked-tile">🔒</div>').join('')}</div>`)+`<nav class="photo-tabs">${button('최근 항목','phone.nav','','data-to="photos"')}${button('앨범','phone.nav','','data-to="albums"')}</nav>`;}
  if(this.page==='notes')return this.head('메모')+`<div class="app-list notes-list">${s.notes.filter(n=>this.isVisible(n)||n.lockedStyle==='placeholder').map(n=>`<button class="list-row" data-action="phone.nav" data-to="note:${n.id}"><div><b>${this.isVisible(n)?esc(n.title):'잠긴 메모'}</b><small>${this.isVisible(n)&&!n.passcode?esc(n.text.slice(0,25)):'🔒'}　${esc(n.date)}</small></div></button>`).join('')}</div>`;
  if(this.page.startsWith('note:')){const n=s.notes.find(x=>x.id===this.page.slice(5));if(!n)return this.head('메모','notes');if(this.mode==='edit')return this.head('메모','notes')+`<article class="note-body" data-action="phone.select-note" data-id="${n.id}"><small>${esc(n.date)}</small><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></article>`;if(!visible(n,p)&&!p.noteUnlocked.includes(n.id))return this.head('메모','notes')+'<div class="empty">🔒<p>아직 열 수 없는 메모입니다.</p></div>';if(!this.canReadNote(n)){const state=p.notePasswords[n.id];const blocked=state?.disabled||state?.until>Date.now();return this.head('메모','notes')+`<div class="note-password"><h2>🔒</h2><h3>잠긴 메모</h3><p>${esc(n.hint)}</p>${blocked?'<p>나중에 다시 시도해 주세요.</p>':`<input id="note-code" type="password" inputmode="numeric" maxlength="${n.passcode.length}" aria-label="메모 암호">${button('잠금 해제','phone.note-unlock','','data-id="'+n.id+'"')}`}${this.noteError?`<p class="error">${esc(n.error)}</p>`:''}</div>`;}return this.head('메모','notes')+`<article class="note-body"><small>${esc(n.date)}</small><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></article>`;}
  if(this.page==='calls')return this.head('최근 통화')+`<div class="app-list">${p.callHistory.slice().reverse().map(c=>`<div class="list-row ${c.status==='missed'?'missed':''}"><div><b>${esc(s.calls.find(x=>x.id===c.id)?.name)}</b><small>${c.status==='missed'?'부재중':c.direction==='out'?'발신':'수신'}</small></div><small>${new Date(c.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')}${!p.callHistory.length?'<div class="empty">최근 통화 없음</div>':''}</div>`;
  if(this.page==='sms')return this.head('메시지')+`<div class="app-list">${s.sms.map(x=>`<button class="list-row" data-action="phone.nav" data-to="sms:${x.id}"><span class="avatar">✉</span><div><b>${esc(x.sender)}</b><small>${esc(x.text)}</small></div></button>`).join('')}</div>`;
  if(this.page.startsWith('sms:')){const x=s.sms.find(x=>x.id===this.page.slice(4));return this.head(x?.sender||'메시지','sms')+`<div class="sms-body"><small>${esc(x?.date)}</small><p>${esc(x?.text)}</p></div>`;}
  if(this.page==='safari')return this.head('Safari')+`<div class="safari-body"><div class="address-bar">⌕　검색 기록</div><h2>최근 검색</h2>${s.safari.map(x=>`<button class="list-row" data-action="phone.nav" data-to="result:${x.id}">◷　${esc(x.keyword)}</button>`).join('')}</div>`;
  if(this.page.startsWith('result:')){const x=s.safari.find(x=>x.id===this.page.slice(7));return this.head('검색 결과','safari')+`<div class="safari-body"><div class="address-bar">${esc(x?.keyword)}</div><h3>${esc(x?.title)}</h3>${image(x?.src)}</div>`;}
  if(this.page==='camera'){const latest=albumPhotos(s,p).at(-1);return `<section class="camera"><div class="camera-tools">ϟ　　　⌃　　　◎</div><div class="camera-view"><video autoplay playsinline muted></video>${!this.stream?`<div class="camera-fallback"><p class="camera-message">${esc(this.cameraError)}</p>${button('다시 시도','phone.camera-retry')}</div>`:''}</div><div class="camera-mode">사진</div><div class="shutter-row"><button data-action="phone.nav" data-to="photos">${image(latest?.src)||'▧'}</button>${button('','phone.shutter','shutter','aria-label="셔터"')}<span>⟳</span></div></section>`;}
  return this.head('홈');
 }
 canReadNote(n){return this.mode==='edit'||this.p.noteUnlocked.includes(n.id)||!n.passcode||this.p.notePasswords[n.id]?.ok;}
 replyConfig(room){const node=this.story.replyNodes.find(n=>n.roomId===room.id&&(!n.afterMessageId||this.p.arrived.includes(n.afterMessageId))&&(!n.gateSwitch||this.p.variables[n.gateSwitch])&&!this.p.replies.some(r=>r.nodeId===n.id));return node?{...room,...node,id:room.id,nodeId:node.id}:this.story.replyNodes.some(n=>n.roomId===room.id)?{...room,replyMode:'readonly'}:room;}
 latestTime({r,ms}){const last=ms.at(-1);if(!last)return 0;if(this.p.factTimes['message.arrived:'+last.id])return this.p.factTimes['message.arrived:'+last.id];return new Date(r.startTime.slice(0,10)+'T'+last.time).getTime()||0;}
 roomAvatar(r){if(r.avatar)return `<span class="avatar">${image(r.avatar)}</span>`;return r.group?`<span class="group-avatar">${(this.p.members[r.id]||r.members).slice(0,4).map(id=>this.avatar(id)).join('')}</span>`:this.avatar(r.characterId);}
 message(m){const s=this.story,mine=m.sender===s.phone.ownerId,q=s.messages.find(x=>x.id===m.quoteId),translate=s.phone.bilingual&&m.type==='text'&&m.zh;let content=esc(m.text);if(m.type==='image')content=`<button data-action="phone.chat-image" data-id="${m.id}">${image(m.src)}</button>`;if(m.type==='voice')content=`${button('▶ 음성 메시지','phone.voice','','data-id="'+m.id+'"')}${m.transcript?button('내용 보기','phone.transcript','','data-id="'+m.id+'"'):''}${(this.transcripts[m.id]??m.transcriptOpen)?`<p>${esc(m.transcript)}</p>`:''}`;if(m.type==='gift')content=`${image(m.src)}<b>선물 도착</b><p>${esc(m.product)}</p>${button('선물 보기','phone.card','','data-id="'+m.id+'"')}`;if(m.type==='transfer')content=`<b>₩ ${esc(m.amount)}</b><p>${m.received?'받기 완료':'송금 대기'}</p>${button('송금 내역','phone.card','','data-id="'+m.id+'"')}`;return `<div class="message ${mine?'mine':''} ${this.focusSender&&m.sender!==this.focusSender?'dimmed':''}" data-message-id="${m.id}">${!mine?button(this.avatar(m.sender),'phone.nav','avatar-button','data-to="profile:'+m.sender+'"'):''}<div>${!mine?button(esc(this.name(m.sender)),'phone.nav','sender-name','data-to="profile:'+m.sender+'"'):''}<div class="bubble ${m.type==='image'?'image-bubble':''} ${this.mode==='edit'?'editable':''}" data-action="phone.select-message" data-id="${m.id}">${q?`<div class="quote">${esc(this.name(q.sender))}<br>${esc(q.type==='text'?q.text:({image:'사진',voice:'음성 메시지',gift:'선물',transfer:'송금'})[q.type])}</div>`:''}${content}${translate?`${button((this.translation[m.id]??s.phone.translationOpen)?'중국어 ▴':'중국어 ▾','phone.translation','translation-toggle','data-id="'+m.id+'"')}${(this.translation[m.id]??s.phone.translationOpen)?`<div class="translation">${esc(m.zh)}</div>`:''}`:''}</div><small class="message-time">${m.failed?'<span class="failed">!</span> ':''}${esc(m.time)}</small></div></div>`;}
 observeMessages(list){this.observer?.disconnect();if(this.mode==='edit')return;this.observer=new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting&&!this.p.facts['message.read:'+x.target.dataset.messageId])this.event('message.read',x.target.dataset.messageId);},{root:list,threshold:.7});list.querySelectorAll('[data-message-id]').forEach(el=>this.observer.observe(el));}
 callDuration(){const seconds=Math.max(0,Math.floor((Date.now()-(this.p.call?.acceptedAt||Date.now()))/1000));return `${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;}
 overlays(){if(this.mode==='edit')return '';const p=this.p,s=this.story;if(p.ending&&!p.endingDismissed){const e=s.endings.find(x=>x.id===p.ending);return `<section class="ending-overlay">${image(e?.src)}<small>이야기의 끝</small><h2>${esc(e?.title)}</h2><p>${esc(e?.text)}</p>${e?.continue?button(esc(e.button),'phone.ending-continue','primary'):''}${button('다시 시작','phone.restart')}</section>`;}if(p.call){const c=s.calls.find(x=>x.id===p.call.id),banner=c?.presentation==='banner'&&!p.call.accepted;return `<section class="call-overlay ${banner?'call-banner':''}"><small>${p.call.accepted?'<span data-call-duration>'+this.callDuration()+'</span>':'수신 전화'}</small><h2>${esc(c?.name)}</h2>${p.call.accepted?`<p>${esc(c?.text)}</p>${this.audioBlocked?'<p>오디오 재생이 차단되었습니다. 문자 내용을 읽을 수 있습니다.</p>':''}<div class="call-tools"><span>♩<small>소리 끔</small></span><span>▦<small>키패드</small></span><span>◖<small>스피커</small></span><span>＋<small>통화 추가</small></span></div>`:''}<div class="call-actions">${p.call.accepted?button('☎','phone.hangup','decline','aria-label="통화 종료"'):`${button('거절','phone.decline','decline')}${button('응답','phone.accept','accept')}`}</div></section>`;}if(p.notification)return `<button class="notification" data-action="phone.notification"><small>KakaoTalk</small><b>${esc(p.notification.title)}</b><span>${esc(p.notification.text)}</span></button>`;return '';}
 renderViewer(){const host=this.root.querySelector('.viewer-host'),v=this.viewer;if(!host)return;if(!v){host.innerHTML='';const grid=this.root.querySelector('.photo-grid');if(grid)grid.scrollTop=this.galleryScroll;return;}const id=v.ids[v.index],photo=this.story.photos.find(x=>x.id===id),src=v.kind==='photos'?photo?.src:v.kind==='chat'?this.story.messages.find(x=>x.id===id)?.src:id;host.innerHTML=`<div class="viewer"><header>${button('닫기','phone.viewer-close')}<span>${v.kind==='chat'?'':`${v.index+1} / ${v.ids.length}`}</span>${v.kind==='photos'&&this.story.phone.savePhotos&&safeSrc(src)?`<a href="${esc(safeSrc(src))}" download="photo">저장</a>`:''}</header><div class="viewer-stage ${v.kind==='photos'?'zoomable':''}">${image(src)}</div>${v.kind==='chat'?'':`<footer>${button(v.kind==='profile'?'↑':'‹','phone.viewer-prev','',v.index===0||v.scale>1?'disabled':'')}${v.kind==='photos'?button(Math.round(v.scale*100)+'%','phone.viewer-reset'):''}${button(v.kind==='profile'?'↓':'›','phone.viewer-next','',v.index===v.ids.length-1||v.scale>1?'disabled':'')}</footer>`}</div>`;this.transform();}
 async click(e){const x=e.target.closest('[data-action]');if(!x)return;const action=x.dataset.action;if(!action.startsWith('phone.'))return;e.stopPropagation();this.initAudio();const id=x.dataset.id;
  if(action==='phone.nav'||action==='phone.back'){const page=x.dataset.to;if(this.mode==='edit'){const [kind,id]=page.split(':'),map={room:'rooms',profile:'characters',note:'notes',sms:'sms',result:'safari',album:'albums'};if(map[kind])this.onSelect(map[kind],id);}this.navigate(page);}
  if(action==='phone.home'){if(this.p.call&&this.mode!=='edit')return;if(this.page==='lock')this.unlock();else this.navigate('home');}
  if(action==='phone.key'){if(x.dataset.key==='⌫')this.code=this.code.slice(0,-1);else if(/^\d$/.test(x.dataset.key))this.code+=x.dataset.key;this.error=false;if(this.code.length===this.story.phone.passcode.length){if(this.code===this.story.phone.passcode){this.dispatch({type:'unlock'},false);this.navigate('home');return;}this.code='';this.error=true;}this.render();}
  if(action==='phone.hint')toast(this.story.phone.hint);
  if(action==='phone.page'){this.homePage=Number(x.dataset.index);this.render();}
  if(action==='phone.filter-all'||action==='phone.filter-unread'){this.filterUnread=action.endsWith('unread');this.render();}
  if(action==='phone.allread')this.dispatch({type:'chat.allread'});
  if(action==='phone.select-message')this.select('messages',id);
  if(action==='phone.select-note')this.select('notes',id);
  if(action==='phone.add-message')this.onSelect('add-message',id);
  if(action==='phone.photo'){if(this.select('photos',id))return;const p=this.story.photos.find(x=>x.id===id);if(p?.trigger==='grid')this.event('photo.grid',id);this.openPhoto(id);}
  if(action==='phone.chat-image'){if(this.select('messages',id))return;this.event('attachment.read',id);this.openViewer('chat',[id]);}
  if(action==='phone.profile-image'){const c=this.char(id);if(this.select('characters',id))return;this.openViewer('profile',c.gallery,Number(x.dataset.index));}
  if(action==='phone.viewer-close'){this.viewer=null;this.renderViewer();}
  if(action==='phone.viewer-prev')this.switchPhoto(-1);if(action==='phone.viewer-next')this.switchPhoto(1);if(action==='phone.viewer-reset')this.zoom(1);
  if(action==='phone.reply-translation'){this.translation['reply:'+id]=!(this.translation['reply:'+id]??this.story.phone.translationOpen);this.render();}
  if(action==='phone.translation'){this.translation[id]=!(this.translation[id]??this.story.phone.translationOpen);this.render();}
  if(action==='phone.transcript'){this.event('attachment.read',id);this.transcripts[id]=!(this.transcripts[id]??this.story.messages.find(x=>x.id===id)?.transcriptOpen);this.render();}
  if(action==='phone.voice'){if(this.select('messages',id))return;this.event('attachment.read',id);const m=this.story.messages.find(x=>x.id===id);if(!safeSrc(m.audio)){this.transcripts[id]=true;this.render();}else if(this.voiceId===id){if(this.voice.paused)this.voice.play().catch(()=>toast('오디오를 재생할 수 없습니다'));else this.voice.pause();}else{this.stopVoice();this.voiceId=id;this.voice=new Audio(safeSrc(m.audio));this.voice.play().catch(()=>toast('오디오를 재생할 수 없습니다'));}}
  if(action==='phone.card'){if(this.select('messages',id))return;this.event('attachment.read',id);const m=this.story.messages.find(x=>x.id===id);const host=this.root.querySelector('.viewer-host');host.innerHTML=`<div class="card-detail">${button('닫기','phone.card-close')}<h2>${esc(m.type==='gift'?m.product:'송금 내역')}</h2>${m.type==='gift'?image(m.src):`<h2>₩ ${esc(m.amount)}</h2>`}<p>${esc(this.name(m.sender))}</p><p>${esc(m.text)}</p>${m.type==='transfer'?`<p>${m.received?'받기 완료':'송금 대기'}</p>`:''}</div>`;}
  if(action==='phone.card-close')this.root.querySelector('.viewer-host').innerHTML='';
  if(action==='phone.note-unlock'){const n=this.story.notes.find(x=>x.id===id),code=this.root.querySelector('#note-code')?.value;this.noteError=code!==n.passcode;this.dispatch({type:'note.password',id,code});}
  if(action==='phone.camera-retry'){this.releaseCamera();this.camera();}
  if(action==='phone.shutter'){if(this.mode==='edit')return;const id=this.story.phone.cameraPhotoId;if(id){this.dispatch({type:'camera'},false);this.viewer={kind:'chat',ids:[],index:0,scale:1,x:0,y:0};const host=this.root.querySelector('.viewer-host');host.innerHTML=`<div class="viewer"><header>${button('닫기','phone.shutter-close')}</header><div class="viewer-stage">${image(this.story.photos.find(x=>x.id===id)?.src)}</div></div>`;}this.root.querySelector('.camera-view')?.animate([{opacity:.1},{opacity:1}],{duration:180});this.beep();}
  if(action==='phone.shutter-close'){this.viewer=null;this.render();}
  if(action==='phone.notification'){const target=this.p.notification?.target;this.dispatch({type:'unlock'},false);this.dispatch({type:'notice.dismiss'},false);this.target(target);}
  if(action==='phone.accept')this.dispatch({type:'call.accept'});if(action==='phone.decline')this.dispatch({type:'call.decline'});if(action==='phone.hangup')this.dispatch({type:'call.hangup'});
  if(action==='phone.profile-call'){if(this.mode==='edit')return;const c=this.char(id);if(c.phoneMode==='call')this.dispatch({type:'call.outgoing',id:c.callId});else if(c.phoneMode==='event')this.dispatch({type:'reply',id:c.id,text:'',eventId:c.eventId,display:false});}
  if(action==='phone.reply'||action==='phone.reply-preset'){const r=this.replyConfig(this.story.rooms.find(x=>x.id===this.page.slice(5))),text=action==='phone.reply'?this.root.querySelector('#reader-reply')?.value:r.replyText;if(text?.trim())this.dispatch({type:'reply',id:r.id,nodeId:r.nodeId,text,zh:action==='phone.reply-preset'?r.replyZh:'',eventId:r.replyEventId,display:r.replyAsMessage});}
  if(action==='phone.typing'&&!this.typing){const r=this.replyConfig(this.story.rooms.find(x=>x.id===this.page.slice(5)));this.typing=true;this.render();const letters=[...r.replyText];let n=0;this.typingTimer=setInterval(()=>{const text=this.root.querySelector('#typing-text');if(text)text.textContent=letters.slice(0,++n).join('');if(n>=letters.length){clearInterval(this.typingTimer);this.typing=false;this.dispatch({type:'reply',id:r.id,nodeId:r.nodeId,text:r.replyText,zh:r.replyZh,eventId:r.replyEventId,display:r.replyAsMessage});}},({slow:180,normal:100,fast:45})[this.story.phone.typingSpeed]);}
  if(action==='phone.ending-continue')this.dispatch({type:'ending.dismiss'});
  if(action==='phone.restart'){const message=this.story.phone.resetPasswords?'진행 상황과 암호 기억을 모두 초기화합니다. 다시 시작할까요?':'진행 상황을 초기화하고 암호 기억은 유지합니다. 다시 시작할까요?';if(confirm(message)){const old=this.p;this.stopCall();this.stopVoice();this.endingAudio?.pause();this.p=initialProgress(this.story);if(!this.story.phone.resetPasswords){this.p.phoneUnlocked=old.phoneUnlocked;this.p.notePasswords=old.notePasswords;}this.page=this.p.phoneUnlocked?'home':'lock';this.dispatch({type:'start'});}}
 }
}



